#include <cerrno>
#include <ctime>
#include <fcntl.h>
#include <iomanip>
#include <iostream>
#include <locale>
#include <sstream>
#include <string>
#include <sys/resource.h>
#include <unistd.h>
#include <vector>

std::string formatDate() {
    std::tm value{};
    value.tm_year = 126; value.tm_mon = 10; value.tm_mday = 15;
    std::ostringstream output;
    output.imbue(std::locale::classic());
    output << std::put_time(&value, "%a, %d %b %Y %H:%M:%S GMT");
    return output.str();
}
int main(int argc, char** argv) {
    const std::string mode = argc > 1 ? argv[1] : "cold";
    rlimit limits{64, 64};
    if (setrlimit(RLIMIT_NOFILE, &limits) != 0) return 2;
    if (mode == "warm") std::cout << formatDate() << '\n';
    std::vector<int> descriptors;
    while (true) {
        int fd = open("/dev/null", O_RDONLY);
        if (fd < 0) break;
        descriptors.push_back(fd);
    }
    if (errno != EMFILE) return 3;
    if (mode == "release") {
        for (int i = 0; i < 2; ++i) { close(descriptors.back()); descriptors.pop_back(); }
    }
    std::cout << formatDate() << '\n';
    for (int fd : descriptors) close(fd);
}
